CREATE TYPE "InboxConversationStatus" AS ENUM ('OPEN','PENDING','SNOOZED','CLOSED','ARCHIVED');
CREATE TYPE "InboxMessageDirection" AS ENUM ('INCOMING','OUTGOING');
CREATE TYPE "InboxMessageDelivery" AS ENUM ('RECEIVED','QUEUED','SENT','DELIVERED','READ','FAILED');
CREATE TABLE "InboxPlatform" ("id" UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"code" TEXT NOT NULL,"label" TEXT NOT NULL,"icon" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "InboxTag" ("id" UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"code" TEXT NOT NULL,"label" TEXT NOT NULL,"color" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "InboxCustomer" ("id" UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"branchId" UUID NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"phone" TEXT NOT NULL,"normalizedPhone" TEXT NOT NULL,"avatarUrl" TEXT,"firstContactAt" TIMESTAMPTZ NOT NULL,"lastActivityAt" TIMESTAMPTZ NOT NULL);
CREATE TABLE "InboxConversation" ("id" UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"customerId" UUID NOT NULL,"platformId" UUID NOT NULL,"status" "InboxConversationStatus" NOT NULL DEFAULT 'OPEN',"previousStatus" "InboxConversationStatus","assignedEmployeeId" UUID,"assignedTeamId" UUID,"unreadCount" INTEGER NOT NULL DEFAULT 0,"lastMessage" TEXT NOT NULL,"lastActivityAt" TIMESTAMPTZ NOT NULL,"closedAt" TIMESTAMPTZ,"deletedAt" TIMESTAMPTZ,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL);
CREATE TABLE "InboxConversationTag" ("conversationId" UUID NOT NULL,"tagId" UUID NOT NULL,"addedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"addedBy" UUID NOT NULL,PRIMARY KEY ("conversationId","tagId"));
CREATE TABLE "InboxMessage" ("id" UUID PRIMARY KEY,"conversationId" UUID NOT NULL,"direction" "InboxMessageDirection" NOT NULL,"senderName" TEXT NOT NULL,"body" TEXT NOT NULL,"sentAt" TIMESTAMPTZ NOT NULL,"delivery" "InboxMessageDelivery" NOT NULL,"retryToken" TEXT,"createdBy" UUID);
CREATE TABLE "InboxMessageAttachment" ("id" UUID PRIMARY KEY,"messageId" UUID NOT NULL,"sourceId" TEXT NOT NULL,"kind" TEXT NOT NULL,"fileName" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"storageKey" TEXT NOT NULL,"ownerAccountId" UUID NOT NULL,"durationSeconds" INTEGER);
CREATE TABLE "InboxStagedAttachment" ("id" UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"ownerAccountId" UUID NOT NULL,"kind" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"storageId" TEXT NOT NULL,"storageName" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ NOT NULL,"consumedAt" TIMESTAMPTZ,"consumedByMessageId" UUID);
CREATE TABLE "InboxInternalNote" ("id" UUID PRIMARY KEY,"conversationId" UUID NOT NULL,"authorEmployeeId" UUID NOT NULL,"authorName" TEXT NOT NULL,"content" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ);
CREATE TABLE "InboxAssignmentHistory" ("id" UUID PRIMARY KEY,"conversationId" UUID NOT NULL,"previousEmployeeId" UUID,"previousTeamId" UUID,"nextEmployeeId" UUID,"nextTeamId" UUID,"actorId" UUID NOT NULL,"actorName" TEXT NOT NULL,"occurredAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "InboxSystemEvent" ("id" UUID PRIMARY KEY,"conversationId" UUID NOT NULL,"type" TEXT NOT NULL,"label" TEXT NOT NULL,"actorId" UUID NOT NULL,"actorName" TEXT NOT NULL,"payload" JSONB,"occurredAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "InboxPlatform_organizationId_code_key" ON "InboxPlatform"("organizationId","code"); CREATE INDEX "InboxPlatform_organizationId_active_idx" ON "InboxPlatform"("organizationId","active");
CREATE UNIQUE INDEX "InboxTag_organizationId_code_key" ON "InboxTag"("organizationId","code"); CREATE INDEX "InboxTag_organizationId_active_idx" ON "InboxTag"("organizationId","active");
CREATE UNIQUE INDEX "InboxCustomer_organizationId_normalizedPhone_key" ON "InboxCustomer"("organizationId","normalizedPhone"); CREATE INDEX "InboxCustomer_organizationId_branchId_lastActivityAt_idx" ON "InboxCustomer"("organizationId","branchId","lastActivityAt"); CREATE INDEX "InboxCustomer_organizationId_normalizedName_idx" ON "InboxCustomer"("organizationId","normalizedName");
CREATE INDEX "InboxConversation_organizationId_deletedAt_lastActivityAt_i_idx" ON "InboxConversation"("organizationId","deletedAt","lastActivityAt","id"); CREATE INDEX "InboxConversation_organizationId_status_lastActivityAt_idx" ON "InboxConversation"("organizationId","status","lastActivityAt"); CREATE INDEX "InboxConversation_organizationId_assignedEmployeeId_lastAct_idx" ON "InboxConversation"("organizationId","assignedEmployeeId","lastActivityAt"); CREATE INDEX "InboxConversation_organizationId_assignedTeamId_lastActivit_idx" ON "InboxConversation"("organizationId","assignedTeamId","lastActivityAt"); CREATE INDEX "InboxConversation_customerId_idx" ON "InboxConversation"("customerId"); CREATE INDEX "InboxConversation_platformId_idx" ON "InboxConversation"("platformId");
CREATE INDEX "InboxConversationTag_tagId_conversationId_idx" ON "InboxConversationTag"("tagId","conversationId"); CREATE UNIQUE INDEX "InboxMessage_conversationId_retryToken_key" ON "InboxMessage"("conversationId","retryToken"); CREATE INDEX "InboxMessage_conversationId_sentAt_id_idx" ON "InboxMessage"("conversationId","sentAt","id"); CREATE INDEX "InboxMessageAttachment_messageId_idx" ON "InboxMessageAttachment"("messageId"); CREATE INDEX "InboxMessageAttachment_ownerAccountId_sourceId_idx" ON "InboxMessageAttachment"("ownerAccountId","sourceId"); CREATE INDEX "InboxInternalNote_conversationId_createdAt_idx" ON "InboxInternalNote"("conversationId","createdAt"); CREATE INDEX "InboxAssignmentHistory_conversationId_occurredAt_idx" ON "InboxAssignmentHistory"("conversationId","occurredAt"); CREATE INDEX "InboxSystemEvent_conversationId_occurredAt_idx" ON "InboxSystemEvent"("conversationId","occurredAt");
CREATE INDEX "InboxStagedAttachment_organizationId_ownerAccountId_consumed_idx" ON "InboxStagedAttachment"("organizationId","ownerAccountId","consumedAt","expiresAt"); CREATE INDEX "InboxStagedAttachment_expiresAt_idx" ON "InboxStagedAttachment"("expiresAt");
ALTER TABLE "InboxPlatform" ADD CONSTRAINT "InboxPlatform_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InboxTag" ADD CONSTRAINT "InboxTag_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InboxCustomer" ADD CONSTRAINT "InboxCustomer_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InboxCustomer" ADD CONSTRAINT "InboxCustomer_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "InboxConversation" ADD CONSTRAINT "InboxConversation_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InboxConversation" ADD CONSTRAINT "InboxConversation_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "InboxCustomer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InboxConversation" ADD CONSTRAINT "InboxConversation_platformId_fkey" FOREIGN KEY ("platformId") REFERENCES "InboxPlatform"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InboxConversation" ADD CONSTRAINT "InboxConversation_assignedEmployeeId_fkey" FOREIGN KEY ("assignedEmployeeId") REFERENCES "Account"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "InboxConversation" ADD CONSTRAINT "InboxConversation_assignedTeamId_fkey" FOREIGN KEY ("assignedTeamId") REFERENCES "TicketTeam"("id") ON DELETE SET NULL ON UPDATE CASCADE;
