ALTER TABLE "InboxStagedAttachment" ADD CONSTRAINT "InboxStagedAttachment_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InboxStagedAttachment" ADD CONSTRAINT "InboxStagedAttachment_ownerAccountId_fkey" FOREIGN KEY ("ownerAccountId") REFERENCES "Account"("id") ON DELETE CASCADE ON UPDATE CASCADE;
